func (this *Test_org_eclipse_swt_graphics_Image) Test_bug566545_efficientGrayscaleImage() {
	var grayscale []*swt.RGB = make([]*swt.RGB, 256)
	for i := int32(0); i < int32(len(grayscale)); i++ {
		grayscale[i] = swt.NewRGB(i, i, i)
	}
	var width int32 = 128
	var height int32 = 128
	var imageDataIndexed *swt.ImageData = swt.NewImageData(width, height, 8, swt.NewPaletteData(grayscale))
	var imageDataDirect *swt.ImageData = swt.NewImageData(width, height, 8, swt.NewPaletteDataRedMaskGreenMaskBlueMask(0xFF, 0xFF, 0xFF))
	var fillImage func(*swt.ImageData) = func(imageData *swt.ImageData) {
		for y := int32(0); y < imageData.Height; y++ {
			for x := int32(0); x < imageData.Width; x++ {
				imageData.SetPixel(x, y, (x+y)%256)
			}
		}
	}
	fillImage(imageDataIndexed)
	fillImage(imageDataDirect)
	var imageIndexed *swt.Image = swt.NewImageDeviceData(upcastswtDisplayToswtDevice(this.display), imageDataIndexed)
	var imageDirect *swt.Image = swt.NewImageDeviceData(upcastswtDisplayToswtDevice(this.display), imageDataDirect)
	var gcDrawer1 swt.ImageGcDrawer = &ImageGcDrawerFunc{fn: func(gc *swt.GC, iWidth int32, iHeight int32) {
		gc.DrawImage(imageIndexed, 0, 0)
	}}
	var outImageIndexed *swt.Image = swt.NewImageDeviceImageGcDrawerWidthHeight(upcastswtDisplayToswtDevice(this.display), gcDrawer1, width, height)
	var gcDrawer2 swt.ImageGcDrawer = &ImageGcDrawerFunc{fn: func(gc *swt.GC, iWidth int32, iHeight int32) {
		gc.DrawImage(imageDirect, 0, 0)
	}}
	var outImageDirect *swt.Image = swt.NewImageDeviceImageGcDrawerWidthHeight(upcastswtDisplayToswtDevice(this.display), gcDrawer2, width, height)
	ImageTestUtilAssertImagesEqual(imageDataIndexed, imageDataDirect)
	ImageTestUtilAssertImagesEqual(imageIndexed.GetImageData(), imageDirect.GetImageData())
	ImageTestUtilAssertImagesEqual(outImageIndexed.GetImageData(), outImageDirect.GetImageData())
	imageIndexed.Dispose()
	imageDirect.Dispose()
	outImageIndexed.Dispose()
	outImageDirect.Dispose()
}

