func Test_org_eclipse_swt_graphics_ImageScaleBounds(rectLike swt.RectangleLike, targetZoom int32, currentZoom int32) *swt.Rectangle {
	var rect *swt.Rectangle
	if rectLike != nil {
		rect = rectLike.AsRectangle()
	}
	_ = rect
	var scaleFactor float32 = (float32(targetZoom)) / float32(currentZoom)
	var returnRect *swt.Rectangle = swt.NewRectangle(0, 0, 0, 0)
	returnRect.X = int32(math.Floor(float64(float32(rect.X)*scaleFactor) + 0.5))
	returnRect.Y = int32(math.Floor(float64(float32(rect.Y)*scaleFactor) + 0.5))
	returnRect.Width = int32(math.Floor(float64(float32(rect.Width)*scaleFactor) + 0.5))
	returnRect.Height = int32(math.Floor(float64(float32(rect.Height)*scaleFactor) + 0.5))
	return returnRect
}

